#include "Runtime.h"
#include <windows.h>
#include <psapi.h>
#include <map>
#include <vector>
#include <chrono>
#include <iostream>
bool setupRuntime(){std::vector<wchar_t> p(32768);DWORD n=GetModuleFileNameW(nullptr,p.data(),static_cast<DWORD>(p.size()));if(!n||n>=p.size())return false;std::error_code ec;auto dir=std::filesystem::path(p.data()).parent_path()/L"data";std::filesystem::create_directories(dir,ec);if(ec)return false;std::filesystem::current_path(dir,ec);return !ec;}
static unsigned long long ft(FILETIME f){return (static_cast<unsigned long long>(f.dwHighDateTime)<<32)|f.dwLowDateTime;}
std::string resources(){FILETIME a,b,k,u;PROCESS_MEMORY_COUNTERS m{};m.cb=sizeof(m);if(!GetProcessTimes(GetCurrentProcess(),&a,&b,&k,&u)||!GetProcessMemoryInfo(GetCurrentProcess(),&m,sizeof(m)))return "Resources: unavailable";static unsigned long long prev=0;static auto last=std::chrono::steady_clock::now();auto now=std::chrono::steady_clock::now();auto total=ft(k)+ft(u);auto elapsed=std::chrono::duration<double>(now-last).count();SYSTEM_INFO si{};GetSystemInfo(&si);std::string cpu=prev&&elapsed>0?std::to_string(100.0*(total-prev)/1e7/elapsed/(si.dwNumberOfProcessors?si.dwNumberOfProcessors:1)):"warming up";prev=total;last=now;return "Resources: CPU %="+cpu+" working set KiB="+std::to_string(m.WorkingSetSize/1024);}
std::string startupChanges(){using Values=std::map<std::wstring,std::vector<BYTE>>;static Values old;static bool ready=false;Values current;unsigned index=0;for(auto hive:{HKEY_CURRENT_USER,HKEY_LOCAL_MACHINE})for(auto path:{L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",L"Software\\Microsoft\\Windows\\CurrentVersion\\RunOnce"}){++index;HKEY key{};auto rc=RegOpenKeyExW(hive,path,0,KEY_QUERY_VALUE,&key);if(rc==ERROR_FILE_NOT_FOUND)continue;if(rc!=ERROR_SUCCESS)return "Registry: incomplete visibility";for(DWORD i=0;i<4096;++i){wchar_t name[16384];DWORD len=16384,type=0,size=65536;std::vector<BYTE> data(size);rc=RegEnumValueW(key,i,name,&len,nullptr,&type,data.data(),&size);if(rc==ERROR_NO_MORE_ITEMS)break;if(rc!=ERROR_SUCCESS||i==4095){RegCloseKey(key);return "Registry: incomplete enumeration";}data.resize(size);for(unsigned j=0;j<4;++j)data.push_back(static_cast<BYTE>(type>>(8*j)));current[std::to_wstring(index)+L":"+std::wstring(name,len)]=std::move(data);}RegCloseKey(key);}if(!ready){old=std::move(current);ready=true;return "Registry: startup baseline initialized";}bool changed=current!=old;old=std::move(current);return changed?"ALERT: registry Run/RunOnce values changed; review manually":"Registry: startup values unchanged";}
